package com.travel.review; import java.time.Instant; public record ReviewView(Long id,Long placeId,Integer stars,String content,String pros,String cons,Integer recommendScore,String enabledFieldsJson,Instant createdAt,Instant updatedAt){static ReviewView from(Review r){return new ReviewView(r.id,r.place.getId(),r.stars,r.content,r.pros,r.cons,r.recommendScore,r.enabledFieldsJson,r.createdAt,r.updatedAt);}}
